def fractional_knapsack(W, values, weights):
    order = sorted(range(len(values)), key=lambda i: values[i] / weights[i], reverse=True)
    loot = 0.0
    for i in order:
        if W <= 0:
            break
        if weights[i] > W:
            loot += W * (values[i] / weights[i])
            W = 0
        else:
            loot += values[i]
            W -= weights[i]
    return loot

