using namespace std;

double fractionalKnapsack(int W, vector<pair<double, double>>& items) {
    // items: {value, weight}; sort by value/weight descending
    sort(items.begin(), items.end(), [](auto& a, auto& b) {
        return a.first / a.second > b.first / b.second;
    });
    double loot = 0;
    for (auto& [value, weight] : items) {
        if (W <= 0) break;
        if (weight > W) {
            loot += W * (value / weight);
            W = 0;
        } else {
            loot += value;
            W -= (int)weight;
        }
    }
    return loot;
}

