import java.util.Arrays;

class Solution {
    public double fractionalKnapsack(int W, int[] values, int[] weights) {
        Integer[] order = new Integer[values.length];
        for (int i = 0; i < order.length; ++i) order[i] = i;
        Arrays.sort(order, (a, b) ->
            Double.compare((double) values[b] / weights[b], (double) values[a] / weights[a]));
        double loot = 0;
        for (int idx : order) {
            if (W <= 0) break;
            if (weights[idx] > W) {
                loot += W * ((double) values[idx] / weights[idx]);
                W = 0;
            } else {
                loot += values[idx];
                W -= weights[idx];
            }
        }
        return loot;
    }
}
